#[test]
#[allow(clippy::disallowed_methods)] // Corpus replay intentionally reads committed seeds.
fn run_test_cases() {
	use std::fs;
	use std::path::Path;
	use loupe_fuzz::utils::test_logger::StringBuffer;

	worker_citation_test(&[0], test_logger::DevNull {});
	let directory = Path::new(env!("CARGO_MANIFEST_DIR")).join("../test_cases/worker_citation");
	let entries = fs::read_dir(&directory)
		.unwrap_or_else(|error| panic!("could not read seed directory {}: {error}", directory.display()));
	let mut paths: Vec<_> = entries.map(|entry| {
		entry.unwrap_or_else(|error| panic!("could not read seed entry: {error}")).path()
	}).collect();
	assert!(!paths.is_empty(), "seed directory is empty: {}", directory.display());
	paths.sort();
	for path in paths {
		let data = fs::read(&path)
			.unwrap_or_else(|error| panic!("could not read seed {}: {error}", path.display()));
		let logger = StringBuffer::new();
		let output = logger.clone();
		if std::panic::catch_unwind(move || worker_citation_test(&data, output)).is_err() {
			panic!("seed failed: {}\n{}", path.display(), logger.into_string());
		}
	}
}
